package com.bank.receipt;

import java.util.*;
import java.util.logging.Logger;

public class DuplicateReceiptsDemo {
    private static final Logger log = Logger.getLogger(DuplicateReceiptsDemo.class.getName());

    public static void main(String[] args) {
        int[] printed = {4, 3, 2, 7, 8, 2, 3, 1};  // n=8, 2 and 3 printed twice
        log.info("Printed receipt numbers: " + Arrays.toString(printed));

        ReceiptAuditor auditor = new ReceiptAuditor();
        List<Integer> dups = auditor.findDuplicateReceipts(printed);

        log.info("Receipts printed twice: " + dups);
    }
}
