package com.bank.receipt;

import java.util.ArrayList;
import java.util.List;

public class ReceiptAuditor {

    public List<Integer> findDuplicateReceipts(int[] printed) {
        int i = 0, n = printed.length;
        while (i < n) {
            int target = printed[i] - 1;
            if (printed[i] != printed[target]) {       // value-guard: dup-safe
                int tmp = printed[i]; printed[i] = printed[target]; printed[target] = tmp;
            } else {
                i++;
            }
        }
        List<Integer> dups = new ArrayList<>();
        for (int idx = 0; idx < n; idx++) {
            if (printed[idx] != idx + 1) dups.add(printed[idx]);  // collect the STORED value
        }
        return dups;
    }
}
